class Gradebook:
    def __init__(self) -> None:
        # Maps assignment name to dict: {"weight": float, "kind": str}
        self.assignments: dict[str, dict] = {}
        # Maps student name to dict of {assignment_name: grade}
        self.grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        grade = float(grade)
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the 2.0 to 5.0 scale.")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if not self.assignments:
            return 0.0

        student_grades = self.grades.get(student, {})

        # Collect quiz assignments and their effective grades (defaulting to 2.0 if unrecorded)
        quizzes = [
            (name, student_grades.get(name, 2.0))
            for name, info in self.assignments.items()
            if info["kind"] == "quiz"
        ]

        # Determine if any quiz should be dropped (lowest quiz if > 1 quiz exists)
        dropped_quiz_name = None
        if len(quizzes) > 1:
            # Drop the quiz with the lowest grade. If tied, dropping any one is valid.
            dropped_quiz_name = min(quizzes, key=lambda item: item[1])[0]

        total_weighted_sum = 0.0
        total_weight = 0.0

        for name, info in self.assignments.items():
            if name == dropped_quiz_name:
                continue

            grade = student_grades.get(name, 2.0)
            weight = info["weight"]

            total_weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_sum / total_weight, 2)
