from collections import defaultdict
from typing import NamedTuple


class Assignment(NamedTuple):
    weight: float
    kind: str


class Gradebook:
    DEFAULT_GRADE: float = 2.0
    MIN_GRADE: float = 2.0
    MAX_GRADE: float = 5.0

    def __init__(self) -> None:
        self.assignments: dict[str, Assignment] = {}
        self.grades: dict[str, dict[str, float]] = defaultdict(dict)

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = Assignment(weight=float(weight), kind=kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        grade = float(grade)
        if not (self.MIN_GRADE <= grade <= self.MAX_GRADE):
            raise ValueError(
                f"Grade {grade} is outside the {self.MIN_GRADE} to {self.MAX_GRADE} scale."
            )
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if not self.assignments:
            return 0.0

        student_grades = self.grades.get(student, {})

        # Identify quiz to drop if there is more than one quiz
        quizzes = [
            (name, student_grades.get(name, self.DEFAULT_GRADE))
            for name, meta in self.assignments.items()
            if meta.kind == "quiz"
        ]
        dropped_quiz = min(quizzes, key=lambda q: q[1])[0] if len(quizzes) > 1 else None

        active_assignments = [
            (student_grades.get(name, self.DEFAULT_GRADE), meta.weight)
            for name, meta in self.assignments.items()
            if name != dropped_quiz
        ]

        total_weight = sum(weight for _, weight in active_assignments)
        if total_weight == 0.0:
            return 0.0

        total_score = sum(grade * weight for grade, weight in active_assignments)
        return round(total_score / total_weight, 2)
